using GovUk.Frontend.AspNetCore.Extensions.Validation.BinaryFileValidators.FileTypes;
using NUnit.Framework;
using System;
using System.Collections;
using System.IO;

namespace GovUk.Frontend.AspNetCore.Extensions.Tests.BinaryFileValidators.FileTypes
{
    internal class ExcelTest
    {
        private class ExcelDataProvider : IEnumerable
        {
            private string _emptyExcelFile = "";
            private string _emptyPowerPoint = " / A5LXw0roCIaBg9enryQiB + gbgeodm3TFoRv79kFgoSbArEvS87O + f / Pr2u3dq3OJBXBGIzlSkakFlZJADJWCZeDiLz1HipNEljHZMKEkhCRKVjSaZ + etHpTDTZAtbQRGTqnbyi18RBSZkOlQWKmr0zKHIZmQDWLP9kAaL1abdBYSQfSVVzmQdqtO + izkXDB / QRvFyQfGgYkuC0Ks14R4WlmkCfoSo0BYZc0TGvBY + YwT8cyWSKrlFQhKvMaO + TanmHBmg5ZZn2DUveCj9PwBIIuM + ";

            public IEnumerator GetEnumerator()
            {
                yield return new object[] { _emptyExcelFile, "myExcelFile.xlsx", true };
                yield return new object[] { _emptyPowerPoint, "myPowerPointFile.ppt", false };
            }
        }

        [TestCaseSource(typeof(ExcelDataProvider))]
        public void Can_identify_valid_excel_file(string data, string filename, bool expected)
        {
            var bytes = Convert.FromBase64String(data);
            var excelValidator = new Excel();
            var memoryStream = new MemoryStream(bytes);

            var isValid = excelValidator.IsMatch(memoryStream, filename);
            memoryStream.Dispose();

            Assert.That(isValid, Is.EqualTo(expected));
        }
    }
}